/**
 * Demo rows the V2 design shows for incidents-v2 — idempotent: running it twice
 * leaves the same rows. Called by the demo seed and by `run.ts --part incidents-v2`.
 * Owner: incidents-v2.
 *
 * On INC-217, the reference incident of the design:
 *  - two decisions taken during the incident, as the timeline records them
 *    (notes of kind "decision") — the post-mortem's Decisions block reads them;
 *  - the team's two comments on the post-mortem (root cause, what went well);
 *  - two people's edits of the summary in the document's history, so the
 *    document reads "generated by Atlas · edited by 2 people" while the
 *    sections nobody touched stay "draft · Atlas".
 * Every row has an id derived from the workspace and a stable key; the demo's
 * words stay in the workspace's language (French), like the rest of its data.
 */
import { createHash } from "node:crypto";
import { and, eq } from "drizzle-orm";
import {
  incidentEvents,
  incidents,
  members,
  postMortemComments,
  postMortemRevisions,
  postMortems,
} from "../../schema/app";
import type { SeedTx } from "./types";

/** A UUID derived from the workspace and a key — the same on every run. */
function sid(tenantId: string, key: string): string {
  const h = createHash("sha256").update(`incidents-v2:${tenantId}:${key}`).digest("hex");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

const MIN = 60_000;

export async function seed(tx: SeedTx, tenantId: string): Promise<void> {
  const [inc] = await tx
    .select({ id: incidents.id, declaredAt: incidents.declaredAt })
    .from(incidents)
    .where(and(eq(incidents.tenantId, tenantId), eq(incidents.number, 217)));
  if (!inc) return;
  const people = await tx
    .select({ id: members.id, name: members.name, email: members.email })
    .from(members)
    .where(eq(members.tenantId, tenantId));
  const who = (email: string) =>
    (people as Array<{ id: string; name: string; email: string }>).find((p) => p.email === email);
  const amelie = who("amelie@skylark.dev");
  const thomas = who("thomas@skylark.dev");
  const karim = who("karim@skylark.dev");
  if (!amelie || !thomas || !karim) return;
  const at = (minutes: number) => new Date(inc.declaredAt.getTime() + minutes * MIN);

  /* ---------- Decisions, in the timeline ---------- */
  const decisions = [
    {
      key: "decision:rollback",
      by: thomas,
      at: at(9),
      title: "Revenir sur le déploiement payments-worker plutôt que corriger à chaud",
      why: "un correctif demande une relecture en pleine nuit ; un retour arrière se défait en dix minutes",
    },
    {
      key: "decision:status-page",
      by: amelie,
      at: at(18),
      title: "Publier sur la page de statut avant le rétablissement complet",
      why: "4 % des paiements en échec, c'est visible des clients",
    },
  ];
  for (const d of decisions) {
    const values = {
      id: sid(tenantId, d.key),
      tenantId,
      incidentId: inc.id,
      kind: "note" as const,
      actorKind: "member" as const,
      actorMemberId: d.by.id,
      actorName: d.by.name,
      payload: { system: "decision", title: d.title, why: d.why },
      occurredAt: d.at,
    };
    await tx
      .insert(incidentEvents)
      .values(values)
      .onConflictDoUpdate({
        target: incidentEvents.id,
        set: { payload: values.payload, occurredAt: values.occurredAt },
      });
  }

  /* ---------- The post-mortem: comments and two people's edits ---------- */
  const [pm] = await tx.select().from(postMortems).where(eq(postMortems.incidentId, inc.id));
  if (!pm) return;
  const day = new Date(inc.declaredAt.getTime() + 24 * 60 * MIN);
  const morning = (h: number, m: number) =>
    new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), h, m));
  const comments = [
    {
      key: "comment:root-cause",
      section: "root_cause",
      by: karim,
      at: morning(7, 12),
      body: "Confirmé sur le diff du déploiement : le chemin de retry ouvre une connexion par tentative et ne la libère jamais au timeout. La PR #418 corrige.",
    },
    {
      key: "comment:went-well",
      section: "went_well",
      by: thomas,
      at: morning(7, 40),
      body: "La note épinglée nous a fait gagner un quart d'heure — faisons de l'épinglage un réflexe du runbook.",
    },
  ];
  for (const c of comments) {
    const values = {
      id: sid(tenantId, c.key),
      tenantId,
      postMortemId: pm.id,
      sectionKey: c.section,
      body: c.body,
      memberId: c.by.id,
      memberName: c.by.name,
      createdAt: c.at,
    };
    await tx
      .insert(postMortemComments)
      .values(values)
      .onConflictDoUpdate({
        target: postMortemComments.id,
        set: { body: values.body, sectionKey: values.sectionKey, createdAt: values.createdAt },
      });
  }
  const edits = [
    { key: "revision:summary-amelie", by: amelie, at: morning(6, 55) },
    { key: "revision:summary-karim", by: karim, at: morning(7, 5) },
  ];
  for (const e of edits) {
    const values = {
      id: sid(tenantId, e.key),
      tenantId,
      postMortemId: pm.id,
      kind: "edit" as const,
      sectionKey: "summary",
      title: pm.title,
      sections: pm.sections,
      actorMemberId: e.by.id,
      actorName: e.by.name,
      createdAt: e.at,
    };
    await tx
      .insert(postMortemRevisions)
      .values(values)
      .onConflictDoUpdate({
        target: postMortemRevisions.id,
        set: { sections: values.sections, createdAt: values.createdAt },
      });
  }
}
